"""Converter mechanics on generated bytes; not field or inspection evidence."""

from __future__ import annotations

import importlib.util
import json
from pathlib import Path
from typing import Any

import numpy as np
import pytest
import rasterio
from pyproj import CRS
from rasterio.enums import ColorInterp
from rasterio.transform import from_origin

TOOL = Path(__file__).resolve().parents[2] / "tools/prepare_public_floreat_inputs.py"
spec = importlib.util.spec_from_file_location("public_source_preparation", TOOL)
assert spec is not None and spec.loader is not None
converter = importlib.util.module_from_spec(spec)
spec.loader.exec_module(converter)


def inputs(tmp_path: Path) -> tuple[Path, dict[str, Any]]:
    sources = tmp_path / "originals"
    sources.mkdir()
    entries = []
    for date in ("2021-08-17", "2022-08-24"):
        for kind in ("orthomosaic", "DSM"):
            path = sources / f"{date}-{kind}.tif"
            ortho = kind == "orthomosaic"
            with rasterio.open(
                path,
                "w",
                driver="GTiff",
                width=8,
                height=8,
                count=4 if ortho else 1,
                dtype="uint8" if ortho else "float32",
                crs="EPSG:7850",
                transform=from_origin(382000, 6468000, 0.25, 0.25),
                nodata=None if ortho else -10000,
            ) as dataset:
                if ortho:
                    pixels = np.full((4, 8, 8), 100, dtype="uint8")
                    pixels[3] = 255
                    pixels[3, 0, 0] = 128
                    dataset.write(pixels)
                    dataset.colorinterp = (
                        ColorInterp.red,
                        ColorInterp.green,
                        ColorInterp.blue,
                        ColorInterp.alpha,
                    )
                else:
                    dataset.write(np.full((1, 8, 8), 12.5, dtype="float32"))
            entries.append(
                {
                    "kind": kind,
                    "captureDate": date,
                    "captureDateBasis": "test-generated date declaration",
                    "localIgnoredOriginal": str(path),
                    "bytes": path.stat().st_size,
                    "sha256": converter.sha256(path),
                    "catalogueUrl": "https://example.invalid/synthetic-fixture",
                }
            )
    manifest = {
        "originals": entries,
        "publisher": "Generated test fixture, not Cambridge Coastcare material",
        "license": "Test fixture",
        "licenseUrl": "https://example.invalid/fixture",
        "attribution": "Generated converter tests; no field evidence",
    }
    path = tmp_path / "manifest.json"
    path.write_text(json.dumps(manifest))
    return path, manifest


def test_derived_identity_preserves_unknowns_and_original_bytes(tmp_path: Path) -> None:
    path, manifest = inputs(tmp_path)
    output = tmp_path / "exports"
    record = converter.prepare(path, output)
    assert record["quantitativeSuitabilityClaim"] is False
    assert record["settings"]["verticalReference"] is None
    assert len(record["files"]) == 4
    for source, derived in zip(manifest["originals"], record["files"], strict=True):
        assert converter.sha256(Path(source["localIgnoredOriginal"])) == source["sha256"]
        assert derived["sourceSha256"] == source["sha256"]
        assert derived["captureStartedAt"] is derived["captureEndedAt"] is None
        assert derived["upstreamSoftwareVersion"] is None
        assert derived["inspectionOutcome"] is None
        assert converter.sha256(output / derived["file"]) == derived["sha256"]
        with rasterio.open(output / derived["file"]) as dataset:
            assert dataset.crs.to_epsg() == 7850
            observed_crs = CRS.from_wkt(dataset.crs.to_wkt())
            assert not observed_crs.is_compound
            assert not observed_crs.is_vertical
            if derived["kind"] == "orthomosaic":
                assert set(np.unique(dataset.read(4))) <= {0, 255}
                assert dataset.read(4)[0, 0] == 0


def test_existing_output_and_original_directory_are_not_overwritten(tmp_path: Path) -> None:
    path, manifest = inputs(tmp_path)
    output = tmp_path / "exports"
    output.mkdir()
    sentinel = output / "user-work"
    sentinel.write_text("preserve")
    with pytest.raises(FileExistsError):
        converter.prepare(path, output)
    assert sentinel.read_text() == "preserve"
    original_parent = Path(manifest["originals"][0]["localIgnoredOriginal"]).parent
    with pytest.raises(ValueError, match="original source directory"):
        converter.prepare(path, original_parent / "new")


@pytest.mark.parametrize("resolution", [0, float("nan"), 0.01, 11])
def test_bad_export_resolution_is_rejected(tmp_path: Path, resolution: float) -> None:
    with pytest.raises(ValueError, match="resolution"):
        converter.prepare(tmp_path / "nonexistent", tmp_path / "output", resolution)


def test_mutated_source_refuses_before_export(tmp_path: Path) -> None:
    path, manifest = inputs(tmp_path)
    manifest["originals"][0]["sha256"] = "0" * 64
    path.write_text(json.dumps(manifest))
    with pytest.raises(ValueError, match="source identity"):
        converter.prepare(path, tmp_path / "output")
    assert not (tmp_path / "output").exists()


def test_finite_pixel_budget_refuses_before_export(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    path, _ = inputs(tmp_path)
    monkeypatch.setattr(converter, "MAX_PIXELS", 16)
    with pytest.raises(ValueError, match="pixel budget"):
        converter.prepare(path, tmp_path / "output")
    assert not (tmp_path / "output").exists()


def test_duplicate_date_kind_cannot_silently_overwrite_an_export(tmp_path: Path) -> None:
    path, manifest = inputs(tmp_path)
    manifest["originals"][1] = manifest["originals"][0]
    path.write_text(json.dumps(manifest))
    with pytest.raises(ValueError, match="one ortho and one DSM"):
        converter.prepare(path, tmp_path / "output")
    assert not (tmp_path / "output").exists()
